param()
$ErrorActionPreference='Stop';$root=$PSScriptRoot;$input=Join-Path $root 'input';$out=Join-Path $root 'outputs';New-Item -ItemType Directory -Force -Path $out | Out-Null
Add-Type -AssemblyName System.IO.Compression.FileSystem
function XmlEscape([string]$s){[System.Security.SecurityElement]::Escape($s)}
function Read-ZipText($path,$name){$z=[IO.Compression.ZipFile]::OpenRead($path);try{$e=$z.GetEntry($name);if($null -eq $e){throw "Missing $name"};$r=[IO.StreamReader]::new($e.Open());$t=$r.ReadToEnd();$r.Dispose();return $t}finally{$z.Dispose()}}
function Write-Pptx($path,$entries){if(Test-Path $path){Remove-Item $path -Force};$fs=[IO.File]::Open($path,[IO.FileMode]::Create);$z=[IO.Compression.ZipArchive]::new($fs,[IO.Compression.ZipArchiveMode]::Create);foreach($k in $entries.Keys){$e=$z.CreateEntry($k);$w=[IO.StreamWriter]::new($e.Open(),[Text.UTF8Encoding]::new($false));$w.Write([string]$entries[$k]);$w.Dispose()};$z.Dispose();$fs.Dispose()}
function New-Cell($text,$width){"<a:tc><a:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:rPr lang='en-US'/><a:t>$(XmlEscape $text)</a:t></a:r></a:p></a:txBody><a:tcPr/></a:tc>"}
function New-Table($items){$x='<p:graphicFrame><p:nvGraphicFramePr><p:cNvPr id="8" name="Performance Table"/><p:cNvGraphicFramePr/><p:nvPr/></p:nvGraphicFramePr><p:xfrm><a:off x="500000" y="1400000"/><a:ext cx="11200000" cy="3600000"/></p:xfrm><a:graphic><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/table"><a:tbl><a:tblPr firstRow="1" bandRow="1"><a:tableStyleId>{5C22544A-7EE6-4342-B048-85BDC9FD1C3A}</a:tableStyleId></a:tblPr><a:tblGrid><a:gridCol w="2200000"/><a:gridCol w="3500000"/><a:gridCol w="2500000"/><a:gridCol w="1500000"/><a:gridCol w="1500000"/></a:tblGrid>'; $x+='<a:tr h="370000">'+(New-Cell 'Student ID' 2200000)+(New-Cell 'Student Name' 3500000)+(New-Cell 'Course' 2500000)+(New-Cell 'Score' 1500000)+(New-Cell 'Grade' 1500000)+'</a:tr>';foreach($i in $items){$x+='<a:tr h="320000">'+(New-Cell $i.StudentId 2200000)+(New-Cell $i.StudentName 3500000)+(New-Cell $i.Course 2500000)+(New-Cell $i.Score 1500000)+(New-Cell $i.Grade 1500000)+'</a:tr>'};return $x+'</a:tbl></a:graphicData></a:graphic></p:graphicFrame>'}
try{$template=Read-ZipText (Join-Path $input 'PerformanceTemplate.pptx') 'ppt/slides/slide1.xml';$items=@(Import-Csv (Join-Path $input 'student_performance.csv'));$title='Student Performance Report - '+(Get-Date -Format 'yyyy-MM-dd');$slide1=$template.Replace('{{REPORT_TITLE}}',(XmlEscape $title));$table=New-Table $items;$slide2="<?xml version='1.0' encoding='UTF-8' standalone='yes'?><p:sld xmlns:a='http://schemas.openxmlformats.org/drawingml/2006/main' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships' xmlns:p='http://schemas.openxmlformats.org/presentationml/2006/main'><p:cSld><p:spTree><p:nvGrpSpPr><p:cNvPr id='1' name=''/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr><p:grpSpPr/><p:sp><p:nvSpPr><p:cNvPr id='2' name='Table title'/><p:cNvSpPr/><p:nvPr/></p:nvSpPr><p:spPr/><p:txBody><a:bodyPr/><a:lstStyle/><a:p><a:r><a:rPr/><a:t>Performance detail table</a:t></a:r></a:p></p:txBody></p:sp>$table</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>";$z=[IO.Compression.ZipFile]::OpenRead((Join-Path $input 'PerformanceTemplate.pptx'));try{$entries=[ordered]@{};foreach($e in $z.Entries){$sr=[IO.StreamReader]::new($e.Open());$entries[$e.FullName]=$sr.ReadToEnd();$sr.Dispose()}}finally{$z.Dispose()};$entries['ppt/slides/slide1.xml']=$slide1;$entries['ppt/slides/slide2.xml']=$slide2;$target=Join-Path $out 'Student_Performance_Report.pptx';Write-Pptx $target $entries;$check1=Read-ZipText $target 'ppt/slides/slide1.xml';$check2=Read-ZipText $target 'ppt/slides/slide2.xml';if($check1.Contains('{{') -or -not $check2.Contains('<a:tbl>')){throw 'PPTX verification failed'};foreach($i in $items){if(-not $check2.Contains((XmlEscape $i.StudentName))){throw "Missing $($i.StudentName) in slide table"}};[pscustomobject]@{Presentation=[IO.Path]::GetFileName($target);SlidesVerified=2;TableElementVerified=$true;StudentRows=$items.Count;PdfExport='Not available in portable runtime'}|ConvertTo-Json|Set-Content (Join-Path $out 'verification.json') -Encoding UTF8;Write-Output "Generated and verified PPTX report with $($items.Count) table rows. PDF export not available."}catch{$_|Out-String|Set-Content (Join-Path $out 'error.log');throw}
